import fitz
import PDFbf

# Define file path
filepath = "WX90YZ.pdf"
doc = fitz.open(filepath)

# Create annotation extractor
annoextractor = PDFbf.extractanno(doc=doc)

# Set page number (page 8 is index 7 in zero-based indexing)
pagenumber = 7

# Define the orders for rectangles (zero-based: rectangle 2 is order 1, etc.)
orders = [1, 3, 5]

# Define table specifications for each order
table_specs = {
    1: [  # For order 1 (rectangle 2)
        {
            "data": [["Sensor ID", "Type", "Location"], ["SEN101", "Temperature", "Zone A"], ["SEN102", "Pressure", "Zone B"]],
            "arrange": [None, [80, 80, 80]],
            "font": "Arial",
            "fontsize": 11
        },
        {
            "data": [["Calibration Date", "Technician", "Next Due"], ["01/06/2024", "Mark Lee", "01/12/2024"], ["02/06/2024", "Linda Green", "02/12/2024"]],
            "fontsize": 10
        }
    ],
    3: [  # For order 3 (rectangle 4)
        {
            "data": [["Alarm ID", "Condition", "Action"], ["ALM001", "High Temp", "Shut Down"], ["ALM002", "Low Pressure", "Alert Operator"]],
            "arrange": [None, [70, 100, 80]],
            "font": "Times New Roman",
            "fontsize": 12
        },
        {
            "data": [["Event Log ID", "Timestamp", "Description"], ["EVT101", "01/06/2024 10:00", "System Start"], ["EVT102", "01/06/2024 12:30", "Temperature Warning"]],
            "arrange": [None, [80, 80, 80]],
            "fontsize": 11
        }
    ],
    5: [  # For order 5 (rectangle 6)
        {
            "data": [["Inspection ID", "Area", "Status"], ["INSP201", "Zone A", "Passed"], ["INSP202", "Zone B", "Requires Action"]],
            "fontsize": 10
        },
        {
            "data": [["Maintenance ID", "Task", "Due Date"], ["MTN301", "Replace Filter", "15/06/2024"], ["MTN302", "Lubricate Bearings", "20/06/2024"]],
            "font": "Arial",
            "fontsize": 11
        }
    ]
}

# Iterate over each order (rectangle)
for order in orders:
    # Extract the rectangle for the current order on the page
    rectangle, rfpoint = annoextractor.getclip_rfpoint(pagenumber=pagenumber, rectangleorder=order)

    # Iterate over each table specification for the current order
    for spec in table_specs[order]:
        # Create argument dictionary with essential and optional parameters
        argument = {
            "clip": rectangle,
            "data": spec["data"]
        }
        if "arrange" in spec:
            argument["arrange"] = spec["arrange"]
        if "font" in spec:
            argument["font"] = spec["font"]
        if "fontsize" in spec:
            argument["fontsize"] = spec["fontsize"]

        # Instantiate table manipulator and add the table
        table_adder = PDFbf.manipulate_table(
            doc=doc,
            pagenumber=pagenumber,
            clip=argument.get("clip"),
            data=argument.get("data"),
            arrange=argument.get("arrange"),
            font=argument.get("font"),
            fontsize=argument.get("fontsize")
        )
        doc = table_adder.addtable()

# Save the updated file
updated_filepath = filepath[:-4] + "_updated.pdf"
doc.save(updated_filepath)
